add_action( 'woocommerce_order_status_processing', 'perfectpixel_notify_when_coupon_used', 20, 2 );
add_action( 'woocommerce_order_status_completed', 'perfectpixel_notify_when_coupon_used', 20, 2 );

function perfectpixel_notify_when_coupon_used( $order_id, $order ) {
	if ( ! $order || $order->get_meta( '_perfectpixel_coupon_notified' ) ) {
		return;
	}
	$watched = array_filter( array_map( 'wc_format_coupon_code', explode( ',', '{{notify_coupon_codes}}' ) ) );
	$used    = array_intersect( $watched, array_map( 'wc_format_coupon_code', $order->get_coupon_codes() ) );
	if ( ! $used ) {
		return;
	}
	$recipient = sanitize_email( '{{notify_coupon_recipient}}' );
	$recipient = $recipient ? $recipient : get_option( 'admin_email' );
	$coupon    = strtoupper( implode( ', ', $used ) );
	$subject   = str_replace( array( '{coupon}', '{order}' ), array( $coupon, $order->get_order_number() ), '{{notify_coupon_subject}}' );
	$body      = sprintf(
		'<p>Παραγγελία: #%s<br>Ημερομηνία: %s<br>Κουπόνι: %s<br>Έκπτωση: %s<br>Σύνολο: %s</p>',
		esc_html( $order->get_order_number() ),
		esc_html( wc_format_datetime( $order->get_date_created() ) ),
		esc_html( $coupon ),
		wp_kses_post( wc_price( $order->get_discount_total(), array( 'currency' => $order->get_currency() ) ) ),
		wp_kses_post( wc_price( $order->get_total(), array( 'currency' => $order->get_currency() ) ) )
	);
	$mailer = WC()->mailer();
	$mailer->send( $recipient, $subject, $mailer->wrap_message( $subject, $body ) );
	$order->update_meta_data( '_perfectpixel_coupon_notified', 1 );
	$order->save();
}
